/**
 * The avatar parts library (shared/avatar/catalog.json), shared with the API.
 * The JSON is generated by shared/avatar/build_catalog.py; never edit it by hand.
 * It is imported as text and parsed once, so TypeScript doesn't infer a type for 500 KB of JSON.
 */
import catalogText from '@shared/avatar/catalog.json?raw'

export type View = 'front' | 'three_quarter' | 'side' | 'back'
export type Point = [number, number]
export type Box = [number, number, number, number] // x, y, w, h in canvas units (0-200)

export interface PaletteEntry {
  id: string
  label: string
  hex: string
  shade: string
  light: string
}

/** Layer art: layer name -> view -> SVG fragment. */
export type LayerArt = Record<string, Partial<Record<View, string>>>

export interface PartOption {
  label: string
  body_types: string[]
  layers?: LayerArt
  by_body?: Record<string, LayerArt>
  states?: Record<string, string>
  art?: string
  views?: Record<string, string>
  coverage?: string[]
  hides?: string[]
  face_ink?: string
}

export interface Category {
  label: string
  options: Record<string, PartOption>
}

export interface Extra {
  label: string
  body_types: string[]
  group?: string
  slot?: string
  layers?: LayerArt
  by_body?: Record<string, LayerArt>
}

export interface PoseDef {
  view: View
  mirror: boolean
  root: Point
  angles: Record<string, number>
  expression?: string
  extras?: { layer: string; bone: string; svg: string }[]
}

export interface BodyType {
  label: string
  kind: string
  face_rig: string
  root: Point
  head_scale: number
  bones: Record<View, Record<string, Point>>
  fragments: Record<string, Record<View, string>>
  defaults: { parts: Record<string, string>; colors: Record<string, string> }
}

export interface Layer {
  kind: 'pose' | 'body' | 'face' | 'part' | 'extra'
  bone: string
  layer: string
  part?: string
  category?: string
  extra?: string
  group?: string
}

export interface FaceRigItem {
  feature: 'eye' | 'brow' | 'nose' | 'mouth'
  at: Point
  side?: 'l' | 'r'
  scale?: Point
}

export interface ExpressionDef {
  eyes: string
  mouth: string
  brows: Record<'l' | 'r', { angle: number; dy: number }>
}

export interface Catalog {
  version: number
  canvas: number
  ink: string
  views: View[]
  palettes: Record<string, PaletteEntry[]>
  color_slots: Record<string, { palette?: string; palette_by_body?: Record<string, string> }>
  color_defaults: Record<string, string>
  bones: Record<string, string>
  body_types: Record<string, BodyType>
  categories: Record<string, Category>
  extras: Record<string, Extra>
  expressions: Record<string, ExpressionDef>
  mouths: Record<string, { front: string }>
  face_rigs: Record<string, Record<View, FaceRigItem[]>>
  layers: Record<View, Layer[]>
  poses: Record<string, PoseDef>
  face_visible: string[]
  head_box: Box
  face_cell: { translate: Point; scale: number }
}

export const catalog: Catalog = JSON.parse(catalogText) as Catalog

